#include "mspa/persistence/state_transfer.hpp"
namespace mspa {namespace{bool same_scale(TimeScale a,TimeScale b){return a.ticks_per_second_num==b.ticks_per_second_num&&a.ticks_per_second_den==b.ticks_per_second_den;}Result<PsychTime>rebase(PsychTime t,PsychTime exported,PsychTime imported,TimeScale s,TimeScale d){if(t.ticks()==0)return PsychTime{};if(t>exported)return make_error(ErrorCode::InvalidState,"exported state contains future timestamp");auto age=convert_time_delta(PsychTime(exported.ticks()-t.ticks()),s,d);if(!age)return *age.error_if();if(age.value_if()->ticks()>imported.ticks())return PsychTime{};return PsychTime(imported.ticks()-age.value_if()->ticks());}Result<void>rebase_prop(Proposition&p,PsychTime ex,PsychTime im,TimeScale s,TimeScale d){if(!p.has_time)return {};auto t=rebase(p.time,ex,im,s,d);if(!t)return *t.error_if();p.time=*t.value_if();return {};}}
Result<void>migrate_agent_state(AgentPsychState&s,std::uint32_t target){if(target!=state_schema_version)return make_error(ErrorCode::VersionMismatch,"unsupported migration target");if(s.schema_version==target)return {};if(s.schema_version==0){s.schema_version=target;return {};}return make_error(ErrorCode::VersionMismatch,"no migration path for agent state");}
Result<ImportResult>import_agent_state(const ExportedAgent&e,const TimeDomain&dest,const ImportOptions&o){if(!e.state.id.valid()||!e.origin_time_domain.valid()||!dest.valid()||!o.destination_id.valid())return make_error(ErrorCode::InvalidArgument,"invalid state/time domain/destination");ImportResult r{};r.original_id=e.state.id;r.effective_id=o.destination_id;r.time_policy=o.time_policy;r.rng_policy=o.rng_policy;r.state=e.state;r.state.id=o.destination_id;auto mig=migrate_agent_state(r.state);if(!mig)return *mig.error_if();if(o.time_policy==ImportTimePolicy::PreserveAbsolute){if(e.origin_time_domain.id!=dest.id||!same_scale(e.origin_time_domain.scale,dest.scale))return make_error(ErrorCode::VersionMismatch,"PreserveAbsolute requires identical time domain and scale");}else if(o.time_policy==ImportTimePolicy::RejectIncompatible){if(e.origin_time_domain.id!=dest.id||!same_scale(e.origin_time_domain.scale,dest.scale))return make_error(ErrorCode::VersionMismatch,"time domains incompatible");}else{auto cv=[&](PsychTime&x)->Result<void>{auto q=rebase(x,e.exported_at,o.import_time,e.origin_time_domain.scale,dest.scale);if(!q)return *q.error_if();x=*q.value_if();return {};};auto x=cv(r.state.last_processed_time);if(!x)return *x.error_if();x=cv(r.state.mood.updated_at);if(!x)return *x.error_if();for(auto&b:r.state.beliefs){x=cv(b.updated_at);if(!x)return *x.error_if();x=rebase_prop(b.proposition,e.exported_at,o.import_time,e.origin_time_domain.scale,dest.scale);if(!x)return *x.error_if();}for(auto&em:r.state.emotions){x=cv(em.started_at);if(!x)return *x.error_if();x=cv(em.updated_at);if(!x)return *x.error_if();}for(auto&g:r.state.goals){x=cv(g.created_at);if(!x)return *x.error_if();x=cv(g.updated_at);if(!x)return *x.error_if();}for(auto&m:r.state.memories){x=cv(m.event_time);if(!x)return *x.error_if();x=cv(m.last_reactivated_at);if(!x)return *x.error_if();x=rebase_prop(m.proposition,e.exported_at,o.import_time,e.origin_time_domain.scale,dest.scale);if(!x)return *x.error_if();}for(auto&le:r.state.learned_expectations){x=cv(le.last_activation);if(!x)return *x.error_if();}}
if(o.rng_policy==RngImportPolicy::RekeyForDestination){DeterministicRng rng(derive_agent_seed(o.destination_seed_root,o.destination_id,0));r.state.rng_state=rng.state();}return r;}
}
